import{_ as t,C as r,o as n,c as i,j as e,a,E as s,a2 as c}from"./chunks/framework.DTdEDYjJ.js";const f=JSON.parse('{"title":"平台与下载","description":"","frontmatter":{},"headers":[],"relativePath":"guide/platforms.md","filePath":"guide/platforms.md"}'),l={name:"guide/platforms.md"};function p(h,o,b,u,m,g){const d=r("PlatformCards");return n(),i("div",null,[o[0]||(o[0]=e("h1",{id:"平台与下载",tabindex:"-1"},[a("平台与下载 "),e("a",{class:"header-anchor",href:"#平台与下载","aria-label":'Permalink to "平台与下载"'},"​")],-1)),o[1]||(o[1]=e("p",null,[a("Bot Studio 的桌面端在电脑上运行 Bot。移动端预览面向交办任务和查看结果。网页演示无需安装，Mac 试点 DMG 需要仓库权限。安装工程预览前请查阅各端条件并核对 "),e("code",null,"SHA256SUMS"),a("。")],-1)),s(d,{compact:"","id-prefix":"platform-guide"}),o[2]||(o[2]=c('<h2 id="archive" tabindex="-1">五端软件包与开发归档清单 <a class="header-anchor" href="#archive" aria-label="Permalink to &quot;五端软件包与开发归档清单 {#archive}&quot;">​</a></h2><p>本站在 <code>/openbot/downloads/</code> 提供部分工程预览、调试构建或源码归档，供开发联调与实机测试。Mac 试点 DMG 由有权限的用户从 GitHub Releases 获取。</p><table tabindex="0"><thead><tr><th>平台</th><th>归档产物</th><th>版本 / 架构</th><th>校验与说明</th></tr></thead><tbody><tr><td><strong>macOS</strong></td><td><a href="https://github.com/Harzva/openbot/releases/tag/v0.14.0" target="_blank" rel="noreferrer">v0.14.0 试点发布（需授权）</a> · <a href="../downloads/openbot-macos-ui-upgrade-1.0.28-r11.patch" download="">UI 升级补丁 v1.0.28-r11</a></td><td><code>v0.14.0</code> / <code>v1.0.28-r11</code> (<code>arm64</code>)</td><td>试点发布含 DMG 和校验值，补丁供源码开发</td></tr><tr><td><strong>Windows</strong></td><td><a href="../downloads/openbot-win32-x64-packaging-kit-1.0.28.tar.gz" download="">openbot-win32-x64-packaging-kit-1.0.28.tar.gz</a></td><td><code>v1.0.28</code> (<code>win32-x64</code>)</td><td>含 <code>package-win.mjs</code>、7 尺寸 <code>icon.ico</code> 与 <code>WinAppCapture</code> 窗口捕获模块（SHA-256 <code>d62012b4...</code>）</td></tr><tr><td><strong>Android</strong></td><td><a href="../downloads/openbot-preview-1.0.0-dev.8.apk" download="">openbot-preview-1.0.0-dev.8.apk</a> · <a href="../downloads/openbot-voice-preview-0.1.0-dev.1.apk" download="">语音预览 APK</a></td><td><code>v1.0.0-dev.8</code> / <code>v0.1.0-dev.1</code></td><td>已在 Android 15（荣耀 Magic）与 Redmi Note 8 实机通过（SHA-256 <code>bf74710b...</code>）</td></tr><tr><td><strong>HarmonyOS</strong></td><td><a href="../downloads/openbot-tablet-0.1.2-huawei-debug.hap" download="">openbot-tablet-0.1.2-huawei-debug.hap</a> · <a href="../downloads/openbot-public-sdk-debug.hap" download="">Public SDK HAP</a></td><td><code>v0.1.2</code> (<code>API 8+</code>)</td><td>华为平板 <code>BKY-W10</code>（HarmonyOS 4.2）实机配对与持久执行通过（SHA-256 <code>1cf68d3c...</code>）</td></tr><tr><td><strong>iOS</strong></td><td><a href="../downloads/openbot-ios-simulator-0.3.0-universal.zip" download="">openbot-ios-simulator-0.3.0-universal.zip</a> · <a href="../downloads/openbot-mobile-web-1.0.28.tar.gz" download="">手机网页资源包</a></td><td><code>v0.3.0</code> (<code>arm64/x86_64</code>) / <code>v1.0.28</code></td><td>独立 <code>openbot-ios</code> 通用模拟器 <code>.app</code> 包（SHA-256 <code>b37ef1c6...</code>）与内置 <code>/phone/</code> 网页包</td></tr><tr><td><strong>校验汇总</strong></td><td><a href="../downloads/SHA256SUMS.txt" download="">SHA256SUMS.txt</a> · <a href="../downloads/releases.json" download="">releases.json</a></td><td>全部五端归档</td><td>下载后请执行 <code>shasum -a 256 -c SHA256SUMS.txt</code> 核对完整性</td></tr></tbody></table><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS {#macos}&quot;">​</a></h2><p>当前 GitHub Releases 最新的 DMG 是 <strong>OpenBot v0.14.0 公司试点预发布</strong>。</p><ul><li><strong>Apple Silicon（arm64）</strong>。取得仓库权限后，在<a href="https://github.com/Harzva/openbot/releases/tag/v0.14.0" target="_blank" rel="noreferrer">试点发布页</a>下载 <code>OpenBot-0.14.0-arm64.dmg</code>，并用同页 <code>SHA256SUMS</code> 核对校验值。</li><li><strong>Intel（x86_64）</strong>。暂无安装包。</li></ul><p>安装、模型接入与首次任务见<a href="./quickstart.html">本机快速开始</a>。当前只有试点预览，尚无稳定渠道。没有仓库权限时可直接打开<a href="/openbot/#product-experience">网页交互预览</a>。</p><p>历史 v0.9.3 为开发预览，v0.10.9 为源码预览且没有对应二进制附件。Bot Studio 1.0.33 已在开发方安装验收，同版本安装包尚未上传。 <a href="https://github.com/Harzva/openbot/releases" target="_blank" rel="noreferrer">GitHub Releases（需授权）</a> · <a href="./status.html">支持范围</a></p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows {#windows}&quot;">​</a></h2><p>Windows 端（<code>win32-x64</code>）正在开发中，已完成三项核心工程适配并在 Windows 实机通过冒烟验证：</p><ul><li><strong>原生窗口与标题栏（Feature #2）</strong>：采用 <code>titleBarStyle: &#39;hidden&#39;</code> 与 46px 主题自适应 <code>titleBarOverlay</code>，支持深浅色模式同步。</li><li><strong>桌面窗口观察（Feature #1）</strong>：基于 <code>desktopCapturer</code> 实现 <code>WinAppCapture</code> 后端（<code>app-observation-win32.cjs</code>）。</li><li><strong>图标与打包管线（Feature #3）</strong>：通过 <code>scripts/make-icon-win.cjs</code> 生成 7 尺寸 PNG 嵌入的 <code>build/icon.ico</code>，由 <code>scripts/package-win.mjs</code> 生成 <code>win32-x64</code> 应用目录（工程归档见 <a href="../downloads/openbot-win32-x64-packaging-kit-1.0.28.tar.gz" download="">openbot-win32-x64-packaging-kit-1.0.28.tar.gz</a>）。</li></ul><p>当前尚无公开 Windows 安装包（如签名 <code>.exe</code> / <code>.msi</code> 安装程序）。完成 Windows 端完整构建清单与公开发布签名验收后，再开放面向普通用户的正式安装包入口。</p><h2 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to &quot;Android {#android}&quot;">​</a></h2><p>移动端正在开发，优先作为电脑或云 Node 的控制端，用于扫码连接、交办任务和查看结果。已有独立 USB 和局域网预览验证，可获取 <a href="../downloads/openbot-preview-1.0.0-dev.8.apk" download="">开发预览 APK</a> 和 <a href="../downloads/openbot-voice-preview-0.1.0-dev.1.apk" download="">语音预览 APK</a>。日常 Mac 整合、局域网真实任务及公网联动仍有待验项目，当前暂无稳定版或应用商店入口。</p><p>连接本机时，手机与电脑通常需要处于同一局域网，电脑需要在线；连接自己的云 Node 时，不要求同一 Wi-Fi。网络、HTTPS 和身份配对要求见<a href="./../deployment/network.html">连接与网络</a>。</p><h2 id="harmonyos" tabindex="-1">HarmonyOS <a class="header-anchor" href="#harmonyos" aria-label="Permalink to &quot;HarmonyOS {#harmonyos}&quot;">​</a></h2><p>鸿蒙端（<code>openbot-harmony/</code>）采用 FA ArkUI 原生连接页与 ArkWeb 会话容器架构，支持华为平板与鸿蒙设备直连 Mac 或自建 Node：</p><ul><li><strong>华为平板实机验证（v0.1.2）</strong>：已在华为平板 <code>BKY-W10</code>（HarmonyOS 4.2.0）完成真机签名安装、竖屏状态栏避让、局域网 HTTPS 扫码配对、冷启动地址保持与主 Bot 真实任务交办闭环（调试预览包见 <a href="../downloads/openbot-tablet-0.1.2-huawei-debug.hap" download="">openbot-tablet-0.1.2-huawei-debug.hap</a>，通用 Public SDK 调试包见 <a href="../downloads/openbot-public-sdk-debug.hap" download="">openbot-public-sdk-debug.hap</a>）。</li><li><strong>安装说明</strong>：华为真机直接安装调试 HAP 需匹配设备 UDID 调试Profile，或通过 <code>hdc</code> / DevEco Studio 签名安装；面向所有设备的华为应用市场公开版本尚在准备中。</li></ul><h2 id="ios" tabindex="-1">iOS <a class="header-anchor" href="#ios" aria-label="Permalink to &quot;iOS {#ios}&quot;">​</a></h2><p>iOS 端正在开发中，同时提供两种接入方式：</p><ul><li><strong>独立原生客户端分包（<code>openbot-ios</code> v0.3.0）</strong>：基于 SwiftUI 与 WebKit 原生构建，已完成 9 组同源安全与连接单测、深浅色自适应主题、微信/飞书配对链接智能提纯、局域网延时与 TLS 根证书预检探针、常用宿主置顶以及内置离线演示工作台。通用架构（<code>arm64</code> + <code>x86_64</code>）iOS 模拟器应用包归档见 <a href="../downloads/openbot-ios-simulator-0.3.0-universal.zip" download="">openbot-ios-simulator-0.3.0-universal.zip</a>。</li><li><strong>内置 <code>/phone/</code> 手机网页通道</strong>：iPhone 与 iPad 用户也可直接通过电脑端「手机连接」二维码在 Safari 零安装扫码接入（网页端归档包见 <a href="../downloads/openbot-mobile-web-1.0.28.tar.gz" download="">openbot-mobile-web-1.0.28.tar.gz</a>）。</li></ul><p>当前可下载的是模拟器工程包和手机网页资源，真机签名、TestFlight 与 App Store 分发尚待验收。</p><h2 id="服务器与桌面应用" tabindex="-1">服务器与桌面应用 <a class="header-anchor" href="#服务器与桌面应用" aria-label="Permalink to &quot;服务器与桌面应用&quot;">​</a></h2><p>已有<a href="./../deployment/self-host.html">自建 Linux Node</a>是远程执行服务，不等同于 Linux 桌面客户端。各端实际能力与前置条件见<a href="./status.html">支持范围</a>和<a href="./requirements.html">运行方式</a>。</p><p>五端工程归档记录截至 2026 年 11 月 6 日，Mac GitHub 下载权限与试点附件核对于 2026 年 11 月 17 日。</p>',25))])}const S=t(l,[["render",p]]);export{f as __pageData,S as default};
